def toml_for(name, category, difficulty, skills):
    tags = [name] + [s.lower().replace(' ', '-') for s in skills]
    return 'schema_version = "1.4"\n\n[metadata]\ndifficulty = "%s"\ncategory = "%s"\ntags = [%s]\n\n[verifier]\ntimeout_sec = 300.0\n\n[agent]\ntimeout_sec = %s\n\n[environment]\nbuild_timeout_sec = 600.0\ncpus = 1\nmemory_mb = 2048\nstorage_mb = 4096\n' % (difficulty, category, ', '.join(json.dumps(x) for x in tags), '1800.0' if difficulty == 'hard' else '900.0')


def build():
    tasks = ROOT / 'tasks'
    tasks.mkdir(parents=True, exist_ok=True)
    provenance = {}
    for name, title, category, difficulty, skills, instruction, files, expected in TASKS:
        d = tasks / name
        (d / 'environment/files').mkdir(parents=True, exist_ok=True)
        (d / 'solution').mkdir(exist_ok=True)
        (d / 'tests').mkdir(exist_ok=True)
        (d / 'task.toml').write_text(toml_for(name, category, difficulty, skills))
        text = '# ' + title + '\n\n' + instruction + '\n\n## Deliverable\n\nWrite the requested artifact under `/app`. Do not modify the input files. The verifier uses additional cases where the contract permits it.\n'
        (d / 'instruction.md').write_text(text)
        for rel, content in files.items():
            p = d / 'environment/files' / rel
            p.parent.mkdir(parents=True, exist_ok=True)
            p.write_text(content)
            provenance[f'{name}/environment/files/{rel}'] = {'origin':'authored-v2-fixture','sha256':hashlib.sha256(content.encode()).hexdigest()}
        (d / 'environment/Dockerfile').write_text('FROM bench-base:python-3.12\n\nWORKDIR /app\n\nCOPY files/ /app/\n')
        answer = json.dumps(expected, indent=2, sort_keys=True) + '\n'
        (d / 'tests/expected.json').write_text(answer)
        test = '''#!/bin/bash
mkdir -p /logs/verifier
reward=0
if [ -f /app/answer.json ] && python3 - /app/answer.json /tests/expected.json <<'PY'
import json, sys
with open(sys.argv[1]) as f: got=json.load(f)
with open(sys.argv[2]) as f: want=json.load(f)
# Tasks may include floating-point reports; exact structural comparison is
# intentional for the deterministic starter cases.
assert got == want, (got, want)
PY
then reward=1; fi
echo "$reward" > /logs/verifier/reward.txt
'''
        (d / 'tests/test.sh').write_text(test)
        (d / 'tests/test.sh').chmod(0o755)
        # Oracle is intentionally independent of the agent image contents.
        oracle = '#!/bin/bash\nset -eu\ncat > /app/answer.json <<\'JSON\'\n' + answer + 'JSON\n'
        (d / 'solution/solve.sh').write_text(oracle)
        (d / 'solution/solve.sh').chmod(0o755)
        # Record every task-owned file, not only the input fixtures.
        for owned in d.rglob('*'):
            if owned.is_file() and owned.parts[-2:] != ('__pycache__', ''):
                rel = str(owned.relative_to(ROOT))
                provenance[rel] = {'origin':'authored-v2-task','sha256':hashlib.sha256(owned.read_bytes()).hexdigest()}
    (ROOT / 'specs').mkdir(exist_ok=True)
    (ROOT / 'specs/provenance.json').write_text(json.dumps({'policy':'clean-room','external_sources':[],'task_files':provenance}, indent=2, sort_keys=True) + '\n')
    print(f'created {len(TASKS)} tasks')

if __name__ == '__main__': build()
